import json,re
ed=json.load(open('data/2026-10-14.json'))
sc=json.load(open('data/2026-10-14.script.json'))
items={}
for s in ed['sections']:
    for it in s['items']:
        items[it['headline']]=json.dumps(it)+' '+s['name']
summ=json.dumps(ed['summary'])
num=re.compile(r'\d[\d,\.]*%?')
for i,b in enumerate(sc['blocks']):
    if b['type']=='item':
        ctx=items.get(b['headline'])
        if ctx is None:
            print('NO MATCH HEADLINE',i,b['headline']); continue
